1	# Inventory API
2	
3	> The Context Inventory is the governed working set, not necessarily the complete durable history of a coding session.
4	
5	This document defines a proposed in-memory MVP API consistent with [Context Model](CONTEXT_MODEL.md). The repository does not currently implement this API. Persistence and retrieval beyond the active process are future scope.
6	
7	## Core interfaces
8	
9	```typescript
10	export type ContextType =
11	  | "goal"
12	  | "task"
13	  | "plan"
14	  | "memory"
15	  | "file"
16	  | "diff"
17	  | "tool_output"
18	  | "terminal_output"
19	  | "test_result"
20	  | "retrieved_content"
21	  | (string & {});
22	
23	export type ContextLifecycleState =
24	  | "ACTIVE"
25	  | "COMPRESSED"
26	  | "TRANSFORMED"
27	  | "ARCHIVED"
28	  | "DROPPED";
29	
30	export interface ContextMetadata {
31	  priority: number;
32	  ageTurns: number;
33	  references: number;
34	  source: string;
35	  compressed: boolean;
36	  transformed: boolean;
37	  pinned: boolean;
38	  [key: string]: unknown;
39	}
40	
41	export interface ContextItem {
42	  id: string;
43	  type: ContextType;
44	  content: string;
45	  tokenCount: number;
46	  createdAt: string;
47	  updatedAt: string;
48	  metadata: ContextMetadata;
49	  state: ContextLifecycleState;
50	  revision: number;
51	  replacesId?: string;
52	  tags?: readonly string[];
53	}
54	
55	export type InventoryEventType =
56	  | "ITEM_ADDED"
57	  | "ITEM_UPDATED"
58	  | "ITEM_REMOVED"
59	  | "ITEM_ARCHIVED"
60	  | "ITEM_STATE_CH

